llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "In male patients with alcoholic cirrhosis, meperidine oral bioavailability was 0.80 ± 0.15, higher than in healthy controls, demonstrating that cirrhosis can increase oral bioavailability of drugs subject to first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Flupirtine, a small molecule with a fluorophenyl and carbamate/ester-like moiety, has oral bioavailability of 90% in healthy volunteers, supporting high F for similar low-MW, moderately polar compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A related heteroaromatic compound achieved 67% oral bioavailability in humans, supporting high F for fused heteroaromatic structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Risperidone has an absolute oral bioavailability of 70% in humans, supporting high F for small lipophilic CNS-type drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Lemborexant, a fused heteroaromatic drug, has at least 87% oral bioavailability in healthy subjects, supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Trovafloxacin, a fluoroaromatic fused-ring drug, has mean absolute oral bioavailability of 87.6% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Melperone, a small lipophilic drug, has absolute oral bioavailability of 67% in healthy volunteers, supporting high F for low-MW, moderately lipophilic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "The closest-scoring analogue showed very slow absorption and oral bioavailability ~10% or less in healthy subjects, providing limited contradictory evidence; its larger, HBD-rich, poorly soluble structure limits transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Under cirrhosis, the balance of evidence favors high oral bioavailability (F ≥ 20%). The most condition-relevant evidence, meperidine in alcoholic cirrhosis, shows increased F due to reduced first-pass metabolism. Multiple structurally related small molecules with favorable physicochemical properties have high oral bioavailability (50–90%). The only low-F analogue has limited transferability because it is larger, more polar, and poorly soluble. The query's ester is a metabolic liability, but cirrhosis may reduce first-pass hydrolysis, and the physicochemical prior is favorable.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Morgan similarities to evidence molecules are low (0.23–0.26), limiting structural transferability.",
    "Only one cirrhosis-specific bioavailability record is available (meperidine), and its structural similarity to the query is modest.",
    "The quantitative effect of cirrhosis on the query's ester hydrolysis and first-pass metabolism is unknown.",
    "The threshold is borderline if healthy-state F is near 20%; cirrhosis-related changes could be decisive but are not directly quantified for this molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

